mapper.select:
SELECT COUNT(DISTINCT t_inventories.book_id) FROM ( SELECT book_id, book_title, author, publisher_name FROM m_books INNER JOIN m_publishers ON m_books.publisher_id = m_publishers.publisher_id WHERE m_books.deleted_flag = 0
AND book_title LIKE CONCAT('%', #{keyword} ,'%')
AND genre_id = #{genreId}
) books INNER JOIN t_inventories ON books.book_id = t_inventories.book_id INNER JOIN m_stores ON t_inventories.store_id = m_stores.store_id WHERE t_inventories.deleted_flag = 0
